INSERT INTO `wp_aioseo_notifications` ( `id`, `slug`, `addon`, `title`, `content`, `type`, `level`, `notification_id`, `notification_name`, `start`, `end`, `button1_label`, `button1_action`, `button2_label`, `button2_action`, `dismissed`, `new`, `created`, `updated`) VALUES
(2, '63e3c68eecdda', NULL, 'Introducing SEO Stats for WordPress - Track Your Keyword Rankings and See Important SEO Metrics with 1-click 🔎 🚀', 'Want to see exactly how your content ranks in search results inside of WordPress? You can do just that with our brand new <strong>Google Search Console integration</strong>!\r\n<br><br>\r\nTrack important keywords and get in-plugin tips to help you grow your traffic. <strong>Plus: Try out the new speed test tool!</strong> 🚀\r\n<br><br>\r\n<strong>Upgrade to AIOSEO 4.3.0 (Elite) TODAY to ignite your SEO and outrank competitors!</strong>\r\n<br><br>\r\n<img src="data:image/png;base64," />', 'success', '["4-x","plus"]', 574, NULL, '2023-06-27 12:55:16', NULL, 'Learn More', 'https://aioseo.com/google-search-console-integration/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-plus&utm_medium=plugin-notification&utm_content=Learn%20More', 'Upgrade AIOSEO Pro 🚀', 'https://aioseo.com/account/downloads/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade%20AIOSEO%20Pro', 1, 0, '2023-02-08 15:58:06', '2023-07-02 16:44:09'),
(3, '63e3c68eee235', NULL, 'AIOSEO 4.2.8: More Control Over Search and Social Snippets with SEO Preview 🔎', 'Get greater control over how your search and social media snippets appear with our <strong>new SEO Preview tool</strong>.\r\n<br><br>\r\nPlus, check how well you’ve set up your page’s SEO by getting an overview of your meta tags and basic SEO.\r\n<br><br>\r\nSo, <strong>update to AIOSEO 4.2.8 TODAY</strong> and boost your rankings and drive more engagement on SERPs and social media!', 'success', '["4-x","all-pro"]', 559, NULL, '2023-02-13 16:21:07', NULL, 'Learn More', 'https://aioseo.com/new-seo-preview-more-control-over-search-and-social-snippets/?utm_source=WordPress&utm_campaign=seo-preview-v4-pro&utm_medium=plugin-notification&utm_content=Learn More', NULL, NULL, 1, 0, '2023-02-08 15:58:06', '2023-02-18 06:59:28'),
(4, '6453d37084c8f', NULL, '🗣️ [AIOSEO 4.3.6] Announcing Content Rankings: SEO Performance Tracking Made Easy', 'Get valuable insights about how your content is performing on search engines using our <strong>NEW Content Rankings report</strong>.\r\n<br><br>\r\nThis includes SEO data to help you <strong>optimize your articles for better rankings</strong>. Plus, you can also easily spot <strong>content decay</strong>, making it easier to combat it.\r\n<br><br>\r\nSo, <strong>upgrade AIOSEO TODAY</strong> and boost your rankings and drive more traffic to your content!', 'success', '["4-x","plus"]', 695, NULL, '2023-06-27 12:55:16', NULL, 'Learn More', 'https://aioseo.com/announcing-content-rankings-seo-performance-tracking-made-easy/?utm_source=WordPress&utm_campaign=content-rankings-v4-plus&utm_medium=plugin-notification&utm_content=Learn%20More', 'Upgrade AIOSEO', 'https://aioseo.com/account/downloads/?utm_source=WordPress&utm_campaign=content-rankings-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade%20AIOSEO', 0, 0, '2023-05-04 15:46:56', '2023-07-02 16:44:08'),
(5, '6478bd7007832', NULL, '[NEW] Set a Primary Category to Customize Breadcrumbs (+ WPCode Integration) 🚀', '<strong>The wait is FINALLY over!</strong> One of our most requested feature is live in AIOSEO 4.3.8! 🎉 🎉\r\n<br><br>\r\nWith the brand-new <strong>Primary Category</strong> feature, you now have <strong>full control over which category displays in your breadcrumb trail</strong>.\r\n<br><br>\r\nPlus: customize your AIOSEO experience with <strong>clickable code snippets</strong> courtesy of WPCode!\r\n<br><br>\r\nUpdate to <strong>AIOSEO 4.3.8 TODAY</strong> to ignite your SEO and outrank competitors!', 'success', '["4-x","plus"]', 745, NULL, '2023-07-25 13:50:35', NULL, 'Learn More', 'https://aioseo.com/announcing-primary-category-and-wpcode-integration/?utm_source=WordPress&utm_campaign=primary-category-v4-plus&utm_medium=plugin-notification&utm_content=Learn%20More', 'Upgrade AIOSEO', 'https://aioseo.com/account/downloads/?utm_source=WordPress&utm_campaign=primary-category-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade%20AIOSEO', 0, 0, '2023-06-01 15:46:56', '2023-07-27 15:53:54'),
(6, '649b03ee44a48', NULL, 'It\'s a Sweet Sixteen Kinda Day! 🥳 🥳', '<img src="data:image/png;base64," />\r\n\r\nWe just had our 16th birthday, and to celebrate, we’re offering you massive discounts on all paid plans. Save <strong>up to 70%</strong> when you purchase a new plan or upgrade TODAY!\r\n<br><br>\r\nPlus, we have a <strong>sweet giveaway</strong> with 3 prizes including a <strong>Pixel 7 Pro, Pixel Tablet and Pixel Buds Pro</strong>!\r\n<br><br>\r\nHurry, this deal won\'t last long, check it out TODAY!', 'success', '["4-x","plus"]', 789, NULL, '2023-06-27 12:55:16', '2023-06-30 00:00:00', 'Upgrade Your AIOSEO Plan NOW! (70% OFF)', 'https://aioseo.com/account/downloads/?utm_source=WordPress&utm_campaign=16th-birthday-sale-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade Your AIOSEO Plan NOW! (70% OFF)', 'Enter Pixel Giveaway!', 'https://aioseo.com/happy-birthday-aioseo/?utm_source=WordPress&utm_campaign=16th-birthday-sale-v4-plus&utm_medium=plugin-notification&utm_content=Enter Pixel Giveaway!', 0, 0, '2023-06-27 15:44:46', '2023-06-29 16:47:12'),
(7, '64c13e49f1ed2', NULL, 'NEW: Announcing the AIOSEO Analyzer Chrome extension!  🚀', 'Speed up content reviews and technical SEO checks. This new free tool is designed for you!\r\n<br><br>\r\nAIOSEO Analyzer gives you a big-picture view of your SEO, bringing problem areas into sharp focus. It works on both unpublished <em>and</em> published pages.\r\n<br><br>\r\nAnd it’s <strong>100% free!</strong> Download it today from the Chrome Web Store. And take it for a test drive!', 'success', '["4-x"]', 809, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/announcing-all-in-one-analyzer-by-aioseo/?utm_source=WordPress&utm_campaign=chrome-extension-v4&utm_medium=plugin-notification&utm_content=Learn%20More', 'Download', 'https://aioseo.com/announcing-all-in-one-analyzer-by-aioseo/?utm_source=WordPress&utm_campaign=chrome-extension-v4&utm_medium=plugin-notification&utm_content=Download', 0, 0, '2023-07-26 15:39:53', '2023-12-05 15:41:12'),
(8, '64c534db91fcf', NULL, '🌴🌞 Embrace the summer vibes with our scorching HOT Summer Sale! 🌞🌴', '<img src="data:image/png;base64," />\r\n\r\nIt\'s time to turn up the heat and celebrate the season in style. Whether you\'re a long-time user or a brand-new one, we\'ve got something special for you!\r\n<br><br>\r\nIn honor of summer, we\'re offering you sensational discounts on all paid plans. Save up to a refreshing 70% when you snag a new plan or upgrade TODAY!\r\n<br><br>\r\nBut don\'t lounge around too long under the sun – this irresistible offer won\'t last forever! So, hurry and dive into our Summer Sale before it\'s gone. Your special deal awaits!\r\n', 'success', '["4-x","plus"]', 814, NULL, '2023-07-28 18:10:46', '2023-08-04 00:00:00', 'Upgrade Your AIOSEO Plan NOW! (70% OFF)', 'https://aioseo.com/account/downloads/?utm_source=WordPress&utm_campaign=summer-sale-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade Your AIOSEO Plan NOW! (70% OFF)', NULL, NULL, 0, 0, '2023-07-29 15:48:43', '2023-08-03 08:58:02'),
(9, '64e77a3e0e86c', NULL, '[New] Improved Crawling and Indexing with AIOSEO 4.4.4 🚀', 'Improve your site’s crawlability and indexability with our improved robots.txt editor. With new directives and advanced functionality, ranking your site on search engines just became easier.\r\n<br><br>\r\nWe’ve also added many more new features to version 4.4.4 of AIOSEO. Check out our announcement for more information.\r\n<br><br>\r\nUpgrade to AIOSEO 4.4.4 today!', 'success', '["4-x","all-pro"]', 834, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/greater-robots-txt-file-customization-for-improved-crawlability/?utm_source=WordPress&utm_campaign=robots-editor-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', NULL, NULL, 0, 0, '2023-08-24 15:41:50', '2023-12-05 15:41:12'),
(10, '650bc108822cd', NULL, '[New] TruSEO Highlighter: Instantly locate readability issues! 😮', 'On-page SEO just got easier with our new TruSEO Highlighter! 😮 Turn on the highlighter to instantly find readability issues on a page. 🥳\r\n<br><br>\r\nThis is our most requested feature! With TruSEO highlighter, you’ll instantly find readability issues flagged by AIOSEO.\r\n<br><br>\r\nUpdate to <strong>AIOSEO 4.4.6 TODAY</strong> to simplify SEO & get traction.', 'success', '["4-x","all-pro"]', 847, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/announcing-truseo-highlighter/?utm_source=WordPress&utm_campaign=truseo-highlighter-v4-pro&utm_medium=plugin-notification&utm_content=Learn%20More', NULL, NULL, 0, 0, '2023-09-21 04:05:28', '2023-12-05 15:41:12'),
(11, '652fff1e72a76', NULL, 'Elevate Your SEO Strategy: Meet Cornerstone Content in AIOSEO 4.4.8! 🚀🔥', 'Introducing Cornerstone Content – your secret weapon to boost search rankings and dominate your niche. 🏆\r\n<br><br>\r\nBuild <em>authority & expertise</em>, improve <em>crawling and indexing</em>, supercharge your <em>semantic SEO</em>, and more with this game-changing addition in <strong>AIOSEO 4.4.8</strong>.\r\n<br><br>\r\nUpgrade today or click to Learn more! 👇🏻👇🏻', 'success', '["4-x","plus"]', 887, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/new-supercharge-your-seo-and-content-strategy-with-cornerstone-content/?utm_source=WordPress&utm_campaign=cornerstone-content-v4-plus&utm_medium=plugin-notification&utm_content=Learn%20More', 'Upgrade Your Plan', 'https://aioseo.com/pricing/?utm_source=WordPress&utm_campaign=cornerstone-content-v4-plus&utm_medium=plugin-notification&utm_content=Upgrade%20Your%20Plan', 0, 0, '2023-10-18 15:51:58', '2023-12-05 15:41:12') ;
