(53426, 'perfmatters_options', 'a:18:{s:14:"disable_emojis";s:1:"1";s:17:"disable_dashicons";s:1:"1";s:16:"disable_rest_api";s:0:"";s:30:"disable_google_maps_exclusions";s:0:"";s:17:"disable_heartbeat";s:0:"";s:19:"heartbeat_frequency";s:0:"";s:20:"limit_post_revisions";s:0:"";s:17:"autosave_interval";s:0:"";s:9:"login_url";s:0:"";s:18:"login_url_behavior";s:0:"";s:17:"login_url_message";s:0:"";s:18:"login_url_redirect";s:0:"";s:6:"assets";a:13:{s:14:"script_manager";s:1:"1";s:13:"js_exclusions";s:0:"";s:17:"delay_js_behavior";s:0:"";s:19:"delay_js_inclusions";s:0:"";s:19:"delay_js_exclusions";s:0:"";s:17:"remove_unused_css";s:1:"1";s:12:"rucss_method";s:4:"file";s:25:"rucss_stylesheet_behavior";s:0:"";s:26:"rucss_excluded_stylesheets";a:11:{i:0;s:80:"https://plugin-theme.local/wp-content/themes/archicon/assets/css/grid.min.css";i:1;s:91:"https://plugin-theme.local/wp-content/plugins/elementor/assets/css/frontend-lite.min.css";i:2;s:95:"https://plugin-theme.local/wp-content/plugins/elementor/assets/lib/swiper/css/swiper.min.css";i:3;s:73:"https://plugin-theme.local/wp-content/uploads/elementor/css/global.css";i:4;s:99:"https://plugin-theme.local/wp-content/plugins/creame-whatsapp-me/public/css/joinchat-btn.min.css";i:5;s:117:"https://plugin-theme.local/wp-content/plugins/archicon-core/assets/plugins/perfect-scrollbar/perfect-scrollbar.css";i:6;s:80:"https://plugin-theme.local/wp-content/themes/archicon/assets/css/main.min.css";i:7;s:95:"https://plugin-theme.local/wp-content/plugins/archicon-core/assets/css/archicon-core.min.css";i:8;s:72:"https://plugin-theme.local/wp-content/uploads/custom-css-js/15085.css";i:9;s:95:"https://plugin-theme.local/wp-content/plugins/archicon-core/assets/css/archicon-core.min.css";i:10;s:72:"https://plugin-theme.local/wp-content/uploads/custom-css-js/15083.css";}s:24:"rucss_excluded_selectors";s:0:"";s:11:"header_code";s:0:"";s:9:"body_code";s:0:"";s:11:"footer_code";s:2264:"<script>\r\n	\r\n	function lazy_load_css(path) {\r\n	\r\n	let type_of_path = typeof path;\r\n	switch (type_of_path) {\r\n		case \'object\':\r\n			var head = document.getElementsByTagName(\'head\')[0]; //Get\'s the head element\r\n			for (let i = 0; i < path.length; i++) {\r\n				//Loops through all the paths\r\n				var link = document.createElement(\'link\'); //Creates a link element\r\n				link.href = path[i]; //Assigns a path to the tag\r\n				link.rel = \'stylesheet\'; //Set it\'s rel to stylesheet\r\n				link.type = \'text/css\'; //Set\'s it\'s type to text/css\r\n				head.appendChild(link); //Appends it to the head of the document.\r\n			}\r\n			break;\r\n		case \'string\': //If the path is a single path\r\n			var head = document.getElementsByTagName(\'head\')[0];\r\n			var link = document.createElement(\'link\'); //Create the link element\r\n			link.href = path; //Assign the value of path to the link\'s href\r\n			link.rel = \'stylesheet\'; //Assign \'stylesheet\' to the link\r\n			link.type = \'text/css\';\r\n			head.appendChild(link); //Appends the link to the head of the document.\r\n			break;\r\n	}\r\n}\r\n\r\n [\'click\', \'scroll\', \'mousemove\', \'touchstart\'].forEach(function(e) {\r\n    window.addEventListener(e, firstInteraction, {\r\n        once: true\r\n    });\r\n});\r\nvar userInteracted = false;\r\n\r\nfunction firstInteraction() {\r\n    if (!userInteracted) {\r\n        userInteracted = true;\r\n		let css_paths = [\'https://fonts.googleapis.com/css?family=Space+Grotesk%3A300%2C400%2C500%2C600%2C700%7CSpace+Grotesk%3A300%2C400%2C500%2C600%2C700&subset=latin-ext&display=swap&ver=1.0.0,https://fonts.googleapis.com/css?family=Roboto%3A100%2C100italic%2C200%2C200italic%2C300%2C300italic%2C400%2C400italic%2C500%2C500italic%2C600%2C600italic%2C700%2C700italic%2C800%2C800italic%2C900%2C900italic%7CRoboto+Slab%3A100%2C100italic%2C200%2C200italic%2C300%2C300italic%2C400%2C400italic%2C500%2C500italic%2C600%2C600italic%2C700%2C700italic%2C800%2C800italic%2C900%2C900italic%7CSpace+Grotesk%3A100%2C100italic%2C200%2C200italic%2C300%2C300italic%2C400%2C400italic%2C500%2C500italic%2C600%2C600italic%2C700%2C700italic%2C800%2C800italic%2C900%2C900italic&display=swap&ver=6.2\',\'https://plugin-theme.local/wp-content/themes/archicon/assets/css/main.min.css\'];\r\n      \r\n	   lazy_load_css(css_paths); \r\n    }\r\n}\r\n\r\n\r\n\r\n\r\n\r\n</script>";}s:7:"preload";a:4:{s:7:"preload";a:0:{}s:15:"critical_images";s:0:"";s:10:"preconnect";a:0:{}s:12:"dns_prefetch";s:0:"";}s:8:"lazyload";a:5:{s:22:"exclude_leading_images";s:0:"";s:26:"youtube_preview_thumbnails";s:1:"1";s:23:"lazy_loading_exclusions";s:0:"";s:9:"threshold";s:0:"";s:24:"css_background_selectors";s:0:"";}s:5:"fonts";a:2:{s:20:"disable_google_fonts";s:1:"1";s:7:"cdn_url";s:0:"";}s:3:"cdn";a:3:{s:7:"cdn_url";s:0:"";s:15:"cdn_directories";s:0:"";s:14:"cdn_exclusions";s:0:"";}s:9:"analytics";a:6:{s:11:"tracking_id";s:0:"";s:22:"tracking_code_position";s:0:"";s:11:"script_type";s:0:"";s:20:"adjusted_bounce_rate";s:0:"";s:7:"cdn_url";s:0:"";s:14:"measurement_id";s:0:"";}}', 'yes'),
