(57128, 'auhfc_settings_sitewide', 'a:9:{s:4:"head";s:289:"<!-- Google tag (gtag.js) -->\r\n<script async src="https://www.googletagmanager.com/gtag/js?id=G-PWW1F3H9QG">\r\n</script>\r\n<script>\r\nwindow.dataLayer = window.dataLayer || [];\r\nfunction gtag(){dataLayer.push(arguments);}\r\ngtag(\'js\', new Date());\r\n\r\ngtag(\'config\', \'G-PWW1F3H9QG\');\r\n</script>";s:10:"priority_h";s:2:"10";s:14:"do_shortcode_h";s:1:"n";s:4:"body";s:0:"";s:10:"priority_b";s:2:"10";s:14:"do_shortcode_b";s:1:"n";s:6:"footer";s:0:"";s:10:"priority_f";s:2:"10";s:14:"do_shortcode_f";s:1:"n";}', 'yes'),
