(14775, 1, '2023-01-24 12:06:42', '0000-00-00 00:00:00', 'add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});', 'Completely Disable Comments', '', 'draft', 'closed', 'closed', '', '', '', '', '2023-01-24 12:06:42', '0000-00-00 00:00:00', '', 0, 'https://plugin-theme.local/?post_type=wpcode&p=14775', 0, 'wpcode', '', 0),
(14870, 1, '2023-03-21 09:21:18', '2023-03-21 09:21:18', '/* Add your JavaScript code here.\r\n\r\nIf you are using the jQuery library, then don\'t forget to wrap your code inside jQuery.ready() as follows:\r\n\r\njQuery(document).ready(function( $ ){\r\n    // Your code in here\r\n});\r\n\r\n--\r\n\r\nIf you want to link a JavaScript file that resides on another server (similar to\r\n<script src="https://example.com/your-js-file.js"></script>), then please use\r\nthe "Add HTML Code" page, as this is a HTML code that links a JavaScript file.\r\n\r\nEnd of comment */ \r\n\r\n	document.addEventListener("DOMContentLoaded", function(){\r\n		let divc = document.querySelectorAll(\'div[style]\');\r\n		for (let i = 0, len = divc.length; i < len; i++) {\r\n			let actdisplay = window.getComputedStyle(divc[i], null).display;\r\n			let actclear = window.getComputedStyle(divc[i], null).clear;\r\n\r\n			if(actdisplay == \'block\' && actclear == \'both\') {\r\n				divc[i].remove();\r\n	}\r\n		}\r\n			});\r\n', 'hide baner', '', 'publish', 'closed', 'closed', '', 'hide-baner', '', '', '2023-03-21 09:21:18', '2023-03-21 09:21:18', '', 0, 'https://plugin-theme.local/?post_type=custom-css-js&#038;p=14870', 0, 'custom-css-js', '', 0),
