none}}@media only screen and (max-width:680px){#qodef-single-post-navigation{margin:49px 0 3px}#qodef-single-post-navigation .qodef-m-nav.qodef--next .qodef-m-nav-image{margin-left:0}#qodef-single-post-navigation .qodef-m-nav-image{display:none}}@media only screen and (max-width:1024px){#qodef-fullscreen-area .qodef-widget-holder{padding:0 5%}#qodef-fullscreen-area .qodef-widget-holder .widget:last-of-type{margin-right:0}}@media only screen and (max-width:680px){#qodef-fullscreen-area .qodef-widget-holder{padding:0 7%}}@media only screen and (max-width:1024px){#qodef-fullscreen-area-inner{display:flex;justify-content:center;flex-direction:column}}@media only screen and (max-width:1440px){.qodef-fullscreen-menu>ul>li>a{font-size:70px}.qodef-fullscreen-menu>ul>li>a .qodef-fullscreen-menu-item-arrow{margin:11px 18px 0 0;max-height:.7em;width:auto}}@media only screen and (max-width:1024px){.qodef-fullscreen-menu .qodef-menu-item-text{justify-content:start}.qodef-fullscreen-menu>ul>li{display:flex;flex-direction:column}.qodef-fullscreen-menu>ul>li .qodef-drop-down-second{margin-left:80px;margin-top:0;position:initial}.qodef-fullscreen-menu::after{display:none}}@media only screen and (max-width:680px){.qodef-fullscreen-menu>ul>li>a{font-size:40px}.qodef-fullscreen-menu>ul>li>a .qodef-fullscreen-menu-item-arrow{height:auto;margin:5px 18px 0 0;width:35px}.qodef-fullscreen-menu>ul>li .qodef-drop-down-second{margin-left:53px}.qodef-fullscreen-menu .qodef-drop-down-second-inner>ul li>a{font-size:25px;margin:16px 0}.qodef-fullscreen-menu .qodef-drop-down-second-inner>ul li>a .qodef-fullscreen-menu-item-arrow{width:25px}}@media only screen and (max-width:1024px){body:not(.qodef-content-behind-header) #qodef-page-outer{margin-top:0!important}}@media only screen and (max-width:1024px){#qodef-top-area{display:none}}@media only screen and (max-width:1440px){.qodef-portfolio-grid-slider .swiper-wrapper .swiper-slide{height:calc((100% - 40px)/ 2)}}@media only screen and (max-width:102