acing:var(--qodef-st-custom-ws-768)}}@media only screen and (max-width:680px){.qodef-section-title .qodef-m-title-inner{font-size:var(--qodef-st-custom-fs-680);letter-spacing:var(--qodef-st-custom-ls-680);line-height:var(--qodef-st-custom-lh-680);word-spacing:var(--qodef-st-custom-ws-680)}.qodef-section-title.qodef-alignment-responsive--left{text-align:left!important}.qodef-section-title.qodef-alignment-responsive--right{text-align:right!important}.qodef-section-title.qodef-alignment-responsive--center{text-align:center!important}.qodef-section-title.qodef-alignment-responsive--justify{text-align:justify!important}}@media only screen and (max-width:1024px){.qodef-page-title .qodef-m-content.qodef-content-full-width{padding:0 5%}body:not(.qodef-content-behind-header) .qodef-page-title .qodef-m-content{padding-top:0!important}}@media only screen and (max-width:680px){.qodef-page-title .qodef-m-content.qodef-content-full-width{padding:0 7%}}', 'archicon-core.min.css', '', 'publish', 'closed', 'closed', '', 'archicon-core-min-css', '', '', '2023-04-03 14:11:17', '2023-04-03 14:11:17', '', 0, 'https://plugin-theme.local/?post_type=custom-css-js&#038;p=15085', 0, 'custom-css-js', '', 0) ;
