(15086, 1, '2023-04-03 14:33:07', '2023-04-03 14:33:07', '#qodef-page-header {\r\n    background: transparent!important;\r\n}\r\n/* .recent_cus_post .qodef-e-info{\r\n	margin-left: 75px;\r\n} */\r\n\r\n\r\n/*GM CSS*/\r\n.single-post .qodef-e-top-holder, .single-post .qodef-e-media-holder {\r\n    display: none !important;\r\n}\r\n.single-post .qodef-e-content {\r\n    padding-top: 50px !important;\r\n}\r\n.qodef-page-title .qodef-m-content {\r\n    justify-content: center !important;\r\n	padding-bottom: 0 !important;\r\n}\r\n.qodef-page-title {\r\n    height: 151px !important;\r\n}\r\n.single-post .qodef-blog .qodef-blog-item {\r\n    margin-bottom: 0 !important;\r\n}\r\n.single-post .comment-form-comment textarea {\r\n    border: 1px solid rgba(0,0,0,.2) !important;\r\n    padding: 15px;\r\n}\r\n.single-post #qodef-page-comments {\r\n    padding-bottom: 50px !important;\r\n}\r\n.single-post p img, .single-post p iframe{\r\n    display: block;\r\n    margin-left: auto !important;\r\n    margin-right: auto !important;\r\n}\r\n\r\n@media (min-width: 782px){\r\n	.category .qodef-blog.qodef-m.qodef--list {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: space-between;\r\n    gap: 24px !important;\r\n}\r\n	.category .qodef-grid .qodef-grid-item {\r\n    padding-top: 50px !important;\r\n}\r\n.category .qodef-blog .qodef-blog-item {\r\n    flex-basis: 48.5% !important;\r\n    width: 48.5% !important;\r\n    background-color: #F8F8F7;\r\n    padding: 20px;\r\n    margin-bottom: 40px !important;\r\n}\r\n}\r\n', 'main css', '', 'publish', 'closed', 'closed', '', '15086', '', '', '2024-03-22 10:23:31', '2024-03-22 10:23:31', '', 0, 'https://plugin-theme.local/?post_type=custom-css-js&#038;p=15086', 0, 'custom-css-js', '', 0) ;
