(1, 'Archicon Bullets', 'archicon-bullets', 'bullets', '.archicon-bullets .tp-bullet {\n    overflow: hidden;\n    width: ##bullet-size##px;\n    height: ##bullet-size##px;\n    background-color: rgba(0, 0, 0, 0);\n    box-shadow: inset 0 0 0 1px ##bullet-color##;\n    transition: background .3s ease;\n    position: absolute;\n}\n\n.archicon-bullets .tp-bullet:after {\n    content: \\\' \\\';\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    background-color: ##bullet-color##;\n    transform-origin: bottom;\n	transform: scaleY(0);\n	transition: .4s ease-out;\n}\n\n.archicon-bullets .tp-bullet.rs-touchhover:after,\n.archicon-bullets .tp-bullet.selected:after {\n    transform: scaleY(1);\n}', '', '{"dim":{"width":"160","height":"160"},"placeholders":{"bullet-size":{"type":"custom","title":"Bullet Size","data":"8"},"bullet-color":{"type":"color","title":"Bullet Color","data":"#ffffff"},"bullet-hover":{"type":"color","title":"Bullet Hover","data":"#ffffff"}},"presets":"","version":"6.0.0"}') ;
