(68, 'wc_admin_BNPL_WCPay_coming-soon_Q1_2023', 'marketing', 'en_US', 'Buy now, pay later is heading to WooCommerce Payments', 'Great news: full integration with Afterpay and Affirm is on its way to WooCommerce Payments! You’ll soon be able to increase your order values, sell more, and offer customers a payment option they’ll love — with no extra downloads or extensions required.', '[]', 'pending', 'woocommerce.com', '2023-04-27 10:28:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'woopay-beta-existingmerchants-noaction-27APR23', 'info', 'en_US', 'WooPay is back!', 'Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.', '[]', 'pending', 'woocommerce.com', '2023-04-28 10:40:42', NULL, 0, 'plain', '', 0, 0, 'info'),
