(83, 'payoneer_q2_2023', 'marketing', 'en_US', 'Grow with the next generation of payment processing', 'Ready to stand out in the new global economy? Payoneer Checkout gives you the power to securely accept payments worldwide, build a checkout that customers love, and manage your store’s transactions and finances – all from the same place.', '[]', 'pending', 'woocommerce.com', '2023-05-14 10:30:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'ipp_refresh_q2_2023_us_inbox_notification', 'marketing', 'en_US', 'Grow on the go with in-person payments', 'Sell your products or services on the go with the M2 card reader – a quick, synchronized, and secure way to take payments, no matter where you are. Create an order using the WooCommerce mobile app and connect your card reader to accept payments.', '[]', 'unactioned', 'woocommerce.com', '2023-05-18 10:28:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'ipp_refresh_q2_2023_ca_inbox_notification', 'marketing', 'en_US', 'Grow on the go with in-person payments', 'Sell your products or services on the go with the WisePad 3 card reader – a quick, synchronized, and secure way to take payments, no matter where you are. Create an order using the WooCommerce mobile app and connect your card reader to accept payments.', '[]', 'pending', 'woocommerce.com', '2023-05-18 10:28:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'product_management_card_sorting', 'survey', 'en_US', 'How do you create and edit products?', 'Have a say in the future of WooCommerce. Take part in a brief exercise and help us understand what information is important to you while editing products.', '[]', 'pending', 'woocommerce.com', '2023-05-19 10:28:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'woocommerce-WCstripe-May-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Stripe plugin', '<strong>Your store requires a security update for the WooCommerce Stripe plugin</strong>. Please update the WooCommerce Stripe plugin immediately to address a potential vulnerability.', '[]', 'pending', 'woocommerce.com', '2023-06-02 10:32:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '[]', 'pending', 'woocommerce.com', '2023-06-03 10:40:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '[]', 'pending', 'woocommerce.com', '2023-06-06 10:33:04', NULL, 0, 'plain', '', 0, 0, 'info'),
(90, 'woocommerce-WCPayments-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Payments', '<strong>Your store requires a security update for the WooCommerce Payments plugin</strong>. Please update the WooCommerce Payments plugin immediately to address a potential vulnerability.', '[]', 'pending', 'woocommerce.com', '2023-06-07 10:34:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(91, 'woocommerce_hpos_1st_notification_q2_2023', 'marketing', 'en_US', 'High-Performance Order Storage (HPOS) is on its way', 'Our team is targeting August 2023 to roll out a major database upgrade that can unlock faster checkout and order creation for your customers — and lightning-quick order lookup for you. Enablement is optional and you won’t be forced to update, but read on to see why this was our most requested new feature.', '[]', 'unactioned', 'woocommerce.com', '2023-06-07 10:34:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(92, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '[]', 'pending', 'woocommerce.com', '2023-06-22 10:30:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(93, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Manage your orders on the go', 'Look for orders, customer info, and process refunds in one click with the Woo app.', '[]', 'unactioned', 'woocommerce-admin', '2023-06-23 10:29:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(94, 'wc-admin-wcpay-bulgaria-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Bulgaria!', 'We’ve recently released WooCommerce Payments in Bulgaria. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(95, 'wc-admin-wcpay-czechia-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Czechia!', 'We’ve recently released WooCommerce Payments in Czechia. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(96, 'wc-admin-wcpay-croatia-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Croatia!', 'We’ve recently released WooCommerce Payments in Croatia. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(97, 'wc-admin-wcpay-hungary-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Hungary!', 'We’ve recently released WooCommerce Payments in Hungary. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(98, 'wc-admin-wcpay-romania-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Romania!', 'We’ve recently released WooCommerce Payments in Romania. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(99, 'wc-admin-wcpay-sweden-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Sweden!', 'We’ve recently released WooCommerce Payments in Sweden. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '[]', 'pending', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(100, 'tiktok-spc_june-2023', 'marketing', 'en_US', 'Take the guesswork out of TikTok advertising', 'Save time and create smarter ads using new automated campaign management from TikTok for WooCommerce. Simplify your campaign creation and watch TikTok’s machine learning build, target, and optimize ads that support your advertising goals — and grow your audience.', '[]', 'unactioned', 'woocommerce.com', '2023-06-30 10:41:57', NULL, 0, 'plain', '', 0, 0, 'info') ;
INSERT INTO `wp_wc_admin_notes` ( `note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(101, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '[]', 'pending', 'woocommerce.com', '2023-07-05 10:32:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(102, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '[]', 'pending', 'woocommerce.com', '2023-07-06 10:37:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(103, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '[]', 'pending', 'woocommerce.com', '2023-07-12 10:36:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(104, 'square_payments_q3_2023', 'marketing', 'en_US', 'Square for WooCommerce', 'Connect your Square account with WooCommerce to accept online and in-person payments (including contactless payments and cross-channel gift cards) quickly and securely. Save time by syncing sales, customers, and items and inventory — and manage everything through one centralized platform.', '[]', 'unactioned', 'woocommerce.com', '2023-07-20 10:30:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(105, 'wc-admin-woopayments-rebrand', 'marketing', 'en_US', 'WooCommerce Payments is now WooPayments', 'We’ve changed the name as part of recent updates to the Woo brand. You’ll still enjoy the same seamless payments experience — just look for WooPayments in your WordPress admin.', '[]', 'pending', 'woocommerce.com', '2023-07-29 10:33:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(106, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '[]', 'pending', 'woocommerce.com', '2023-08-03 10:33:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(107, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '[]', 'pending', 'woocommerce.com', '2023-08-03 10:33:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(108, 'woocommerce-WooPayments-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooPayments (WooCommerce Payments) plugin', '<strong>Your shop requires an important security update for the WooPayments (WooCommerce Payments) extension</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '[]', 'pending', 'woocommerce.com', '2023-08-03 10:33:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(109, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '[]', 'pending', 'woocommerce.com', '2023-08-03 10:33:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(110, 'tiktok-apac-webinar-2023', 'marketing', 'en_US', 'Unlocking TikTok: Live Webinar August 9', 'Join us on August 9 for a free online masterclass with our partners at TikTok, tailored to Woo merchants in the APAC region (11 am AEST). You’ll learn how to connect your store to TikTok, unlock expert advertising tools, and reach its one billion active global users — all from the comfort of your own home.', '[]', 'pending', 'woocommerce.com', '2023-08-05 10:28:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(111, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '[]', 'pending', 'woocommerce.com', '2023-08-09 10:30:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(112, 'avalara_q3-2023_withAvaTax', 'marketing', 'en_US', 'New in AvaTax: Calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '[]', 'pending', 'woocommerce.com', '2023-08-09 10:30:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(113, 'google_uxstudy_recruitment_q3-2023', 'marketing', 'en_US', 'Share your feedback in exchange for $150', 'Woo has teamed up with Google to collect feedback on advertising products and services available to you. If selected, you’ll receive an incentive equal to $150 USD for a 60-minute interview that can help improve the products you use to advertise. If interested, please take 2 minutes to complete the screening survey.', '[]', 'pending', 'woocommerce.com', '2023-08-10 10:43:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(114, 'woo-activation-survey-blockers-22AUG23', 'info', 'en_US', 'How can we help you get that first sale?', 'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!', '[]', 'pending', 'woocommerce.com', '2023-08-23 10:32:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(115, 'tiktok_shopGTM_q3-2023_hasTikTok', 'marketing', 'en_US', 'You can now sell your products on TikTok Shop', 'TikTok is changing the way shoppers find and connect with brands. With TikTok Shop, you can sync your entire catalog from within Woo and sell directly to TikTok users through in-feed videos, livestreams, and your product showcase tab.', '[]', 'pending', 'woocommerce.com', '2023-09-07 11:04:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(116, 'tiktok_shopGTM_q3-2023_noTikTok', 'marketing', 'en_US', 'You can now sell your products on TikTok Shop', 'TikTok is changing the way shoppers find and connect with brands. With TikTok Shop, you can sync your entire catalog from within Woo and sell directly to TikTok users through in-feed videos, livestreams, and your product showcase tab.', '[]', 'pending', 'woocommerce.com', '2023-09-08 10:52:49', NULL, 0, 'plain', '', 0, 0, 'info'),
(117, 'klaviyo_q3_2023', 'marketing', 'en_US', 'Build long lasting relationships with Klaviyo for WooCommerce', 'Increase customer engagement and boost conversions with powerful email and SMS automation from Klaviyo. Fully integrated with your Woo store, Klaviyo enables you to send personalized communications to your customers — ensuring that the right message is delivered at the right time for maximum impact.', '[]', 'pending', 'woocommerce.com', '2023-09-12 10:37:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(118, 'wc_admin_BNPL_WCPay_Q3_2023', 'marketing', 'en_US', 'Afterpay and Affirm have arrived in WooCommerce Payments!', 'Give your customers more power with buy now, pay later from Afterpay and Affirm — now included as part of WooCommerce Payments! With this new integration, you can quickly offer a checkout option that converts sales and boosts average order value, all from within the same payments dashboard you already know.', '[]', 'pending', 'woocommerce.com', '2023-09-19 10:41:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(119, 'wc_admin_afterpay_WCPay_Q3_2023', 'marketing', 'en_US', 'Afterpay has arrived in WooCommerce Payments!', 'Give your customers more power with buy now, pay later from Afterpay — now included as part of WooCommerce Payments! With this new integration, you can quickly offer a checkout option that converts sales and boosts average order value, all from within the same payments dashboard you already know.', '[]', 'pending', 'woocommerce.com', '2023-09-19 10:41:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(120, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href="https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/" />Read our developer update</a> for more information.', '[]', 'pending', 'woocommerce.com', '2023-09-20 11:08:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(121, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Track your store performance on mobile', 'Monitor your sales and high performing products with the Woo app.', '[]', 'unactioned', 'woocommerce-admin', '2023-09-21 10:47:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(122, 'Klarna_10OCT23', 'marketing', 'en_US', 'Klarna is now available', 'This is a test. Klarna is now available.', '[]', 'pending', 'woocommerce.com', '2023-10-11 10:28:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(123, 'wc_com_in_person_payments_card_sale_US_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our M2 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.', '[]', 'pending', 'woocommerce.com', '2023-10-13 10:32:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(124, 'wc_com_in_person_payments_card_sale_UK_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends 29th October 2023.', '[]', 'pending', 'woocommerce.com', '2023-10-13 10:32:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(125, 'wc_com_in_person_payments_card_sale_CA_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.', '[]', 'pending', 'woocommerce.com', '2023-10-13 10:32:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(126, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '[]', 'pending', 'woocommerce.com', '2023-10-18 10:31:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(127, 'wc_admin_WooPay_Q4_2023', 'marketing', 'en_US', 'Convert more sales with our fastest checkout yet', 'Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.', '[]', 'pending', 'woocommerce.com', '2023-10-28 10:28:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(128, 'wc_admin_WooPay_Oct30_2023', 'marketing', 'en_US', 'Convert more sales with our fastest checkout yet', 'Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.', '[]', 'pending', 'woocommerce.com', '2023-11-03 10:32:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(129, 'paypal_paylater_q4_23', 'marketing', 'en_US', 'Boost your sales this holiday season with PayPal', 'Set yourself up for success this holiday season by allowing customers to pay the way they prefer. With the latest version of PayPal Payments, you can accept PayPal, Venmo (US), Pay Later*, credit and debit cards, and popular alternative payment methods in one secure solution.', '[]', 'pending', 'woocommerce.com', '2023-11-07 10:35:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(130, 'tap_to_pay_iphone_q4_2023_no_woopayments', 'marketing', 'en_US', 'Accept in-person contactless payments on your iPhone', 'Tap to Pay on iPhone and WooPayments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.', '[]', 'pending', 'woocommerce.com', '2023-12-06 10:50:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(131, 'tap_to_pay_iphone_q4_2023_with_woopayments', 'marketing', 'en_US', 'Accept in-person contactless payments on your iPhone', 'Tap to Pay on iPhone is quick, secure, and simple to set up in WooPayments — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person in a few short steps!', '[]', 'pending', 'woocommerce.com', '2023-12-06 10:50:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(132, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '[]', 'pending', 'woocommerce.com', '2023-12-07 10:38:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(133, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Edit products on the move', 'Edit and create new products from your mobile devices with the Woo app', '[]', 'unactioned', 'woocommerce-admin', '2023-12-25 10:31:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(134, 'amazon_pay_reactivate_q1-24', 'marketing', 'en_US', 'Special offer: Activate 0% promo rate for Amazon Pay', 'For a limited time, Woo merchants who register with Amazon Pay can enjoy a promotional rate of 0% on all transaction fees for 30 days. Valid for businesses based in the United Kingdom. Terms and conditions apply.', '[]', 'pending', 'woocommerce.com', '2024-01-10 10:31:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(135, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '[]', 'pending', 'woocommerce.com', '2024-01-19 10:31:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(136, 'custom_order_attribution_inbox_q1_2024', 'marketing', 'en_US', 'NEW: Custom Order Attribution', 'Order attribution tracking is now available for all Woo stores! See whether an order came from a search ad, video, or email. Make better marketing decisions and watch your products go from “maybe” to “must-have.”', '[]', 'pending', 'woocommerce.com', '2024-02-06 10:45:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(137, 'wc_admin_UKpricingchange_WCPay_Q1_2024', 'marketing', 'en_US', 'Fee Changes for WooPayments in the EEA and UK', 'WooPayments fees for transactions between the EEA and UK will change as of 1st March, 2024. Transactions between the UK and EEA are now deemed by card networks to be cross-border, thus international payment fees will be applicable. This also changes base processing fees.', '[]', 'pending', 'woocommerce.com', '2024-03-01 10:40:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(138, 'airwallex_q1_2024', 'marketing', 'en_US', 'Save big on foreign exchange (FX) fees', 'Boost your international sales by offering Apple Pay, Google Pay, and 60+ local payment methods with Airwallex. Save time and money by settling payments directly in USD, EUR, HKD, SGD, AUD, and more — without the extra FX fees. Simple, cost-effective, fast.', '[]', 'unactioned', 'woocommerce.com', '2024-03-01 10:40:15', NULL, 0, 'plain', '', 0, 0, 'info') ;
